  1	import type {
  2	  NewProject,
  3	  NewTestSuite,
  4	  Placement,
  5	  ProjectChanges,
  6	  ProjectDeletion,
  7	  TestCase,
  8	  TestLinkClient,
  9	  TestLinkContent,
 10	  TestSuiteChanges,
 11	} from '../src/testlink-client.js'
 12	
 13	/** What the stub answers a Project listing with, for a test to read back. */
 14	export const stubProjects = [{ id: '12', name: 'Wireless', prefix: 'WL' }]
 15	
 16	/** What the stub answers a Test Case listing with, for a test to read back. */
 17	export const stubTestCasesInSuite = [{ id: '5074', name: 'Guest joins the open SSID' }]
 18	
 19	/** Substitutes for TestLink, recording what was written through and what it holds. */
 20	export class StubTestLinkClient implements TestLinkClient {
 21	  readonly written: { placement: Placement; testCase: TestCase }[] = []
 22	  readonly updated: { id: string; testCase: TestCase }[] = []
 23	  readonly deleted: string[] = []
 24	  readonly suitesWritten: { projectId: string; suite: NewTestSuite; parentSuiteId?: string }[] = []
 25	  readonly listed: { projectId: string; parentSuiteId?: string }[] = []
 26	
 27	  readonly projectsWritten: NewProject[] = []
 28	  readonly projectsUpdated: { projectId: string; changes: ProjectChanges }[] = []
 29	
 30	  private readonly heldCases = new Map<string, TestCase>()
 31	  private readonly heldSuites = new Set<string>()
 32	  /** The Projects TestLink holds, each against the prefix a delete must restate. */
 33	  private readonly heldProjects = new Map<string, string>()
 34	
 35	  /** Standing in for TestLink being unreachable, which is not a Rejection. */
 36	  constructor(private readonly reachable = true) {}
 37	
 38	  /**
 39	   * Puts content in TestLink without it passing the write path, which is how
 40	   * content the Rules would fire on comes to be there at all. Held content and
 41	   * written content are kept apart deliberately: a read is set up by saying
 42	   * what TestLink holds, never by first getting content past the Rules.
 43	   */
 44	  hold(id: string, testCase: TestCase): void {
 45	    this.heldCases.set(id, testCase)
 46	  }
 47	
 48	  /** Says TestLink holds this Test Suite, so a write placed in it has somewhere to land. */
 49	  holdSuite(suiteId: string): void {
 50	    this.heldSuites.add(suiteId)
 51	  }
 52	
 53	  /** Says TestLink holds this Project, so a Suite created in it has somewhere to land. */
 54	  holdProject(projectId: string, prefix = 'WL'): void {
 55	    this.heldProjects.set(projectId, prefix)
 56	  }
 57	
 58	  async createTestCase(
 59	    placement: Placement,
 60	    testCase: TestCase,
 61	  ): Promise<{ id: string } | undefined> {
 62	    this.reach()
 63	
 64	    if (!this.heldSuites.has(placement.suiteId)) {
 65	      return undefined
 66	    }
 67	
 68	    this.written.push({ placement, testCase })
 69	    return { id: `testlink-${this.written.length}` }
 70	  }
 71	
 72	  async getTestCase(id: string): Promise<TestCase | undefined> {
 73	    this.reach()
 74	
 75	    return this.heldCases.get(id)
 76	  }
 77	
 78	  async updateTestCase(id: string, testCase: TestCase): Promise<boolean> {
 79	    this.reach()
 80	
 81	    if (!this.heldCases.has(id)) {
 82	      return false
 83	    }
 84	
 85	    this.heldCases.set(id, testCase)
 86	    this.updated.push({ id, testCase })
 87	    return true
 88	  }
 89	
 90	  async deleteTestCase(id: string): Promise<boolean> {
 91	    this.reach()
 92	
 93	    if (!this.heldCases.delete(id)) {
 94	      return false
 95	    }
 96	
 97	    this.deleted.push(id)
 98	    return true
 99	  }
100	
101	  async listProjects(): Promise<TestLinkContent> {
102	    this.reach()
103	
104	    return stubProjects
105	  }
106	
107	  async createProject(project: NewProject): Promise<{ id: string }> {
108	    this.reach()
109	    this.projectsWritten.push(project)
110	
111	    const id = `project-${this.projectsWritten.length}`
112	    this.heldProjects.set(id, project.prefix)
113	    return { id }
114	  }
115	
116	  async updateProject(projectId: string, changes: ProjectChanges): Promise<boolean> {
117	    this.reach()
118	
119	    if (!this.heldProjects.has(projectId)) {
120	      return false
121	    }
122	
123	    this.projectsUpdated.push({ projectId, changes })
124	    return true
125	  }
126	
127	  async deleteProject(projectId: string, confirmPrefix: string): Promise<ProjectDeletion> {
128	    this.reach()
129	
130	    const prefix = this.heldProjects.get(projectId)
131	
132	    if (prefix === undefined) {
133	      return 'absent'
134	    }
135	
136	    if (prefix !== confirmPrefix) {
137	      return 'unconfirmed'
138	    }
139	
140	    this.heldProjects.delete(projectId)
141	    return 'deleted'
142	  }
143	
144	  async listTestSuites(
145	    projectId: string,
146	    parentSuiteId?: string,
147	  ): Promise<TestLinkContent | undefined> {
148	    this.reach()
149	    this.listed.push({ projectId, parentSuiteId })
150	
151	    if (!this.heldProjects.has(projectId)) {
152	      return undefined
153	    }
154	
155	    return [...this.heldSuites].map((id) => ({ id }))
156	  }
157	
158	  async listTestCasesInSuite(suiteId: string): Promise<TestLinkContent | undefined> {
159	    this.reach()
160	
161	    if (!this.heldSuites.has(suiteId)) {
162	      return undefined
163	    }
164	
165	    return stubTestCasesInSuite
166	  }
167	
168	  async createTestSuite(
169	    projectId: string,
170	    suite: NewTestSuite,
171	    parentSuiteId?: string,
172	  ): Promise<{ id: string } | undefined> {
173	    this.reach()
174	
175	    if (!this.heldProjects.has(projectId)) {
176	      return undefined
177	    }
178	
179	    this.suitesWritten.push({ projectId, suite, parentSuiteId })
180	    const id = `suite-${this.suitesWritten.length}`
181	    this.heldSuites.add(id)
182	    return { id }
183	  }
184	
185	  async updateTestSuite(
186	    _projectId: string,
187	    suiteId: string,
188	    _changes: TestSuiteChanges,
189	  ): Promise<boolean> {
190	    this.reach()
191	
192	    return this.heldSuites.has(suiteId)
193	  }
194	
195	  async deleteTestSuite(suiteId: string): Promise<boolean> {
196	    this.reach()
197	
198	    return this.heldSuites.delete(suiteId)
199	  }
200	
201	  private reach(): void {
202	    if (!this.reachable) {
203	      throw new Error('TestLink is unreachable.')
204	    }
205	  }
206	}
