213	/** Substitutes for the database, holding the Reference Documents a test serves. */
214	export class StubDocumentStore implements DocumentStore {
215	  private readonly held = new Map<string, ReferenceDocument>()
216	
217	  /** Standing in for the database being unreachable, which is not a Rejection. */
218	  constructor(private readonly reachable = true) {}
219	
220	  /**
221	   * Puts a Reference Document in the store without it passing any Rule, which is
222	   * how content the Rules fire on comes to be there at all. Documents are written
223	   * by an operator rather than through this API, so this is the only way one
224	   * arrives.
225	   */
226	  hold(id: string, document: ReferenceDocument): this {
227	    this.held.set(id, document)
228	    return this
229	  }
230	
231	  async listDocuments(): Promise<ListedReferenceDocument[]> {
232	    this.reach()
233	
234	    return [...this.held].map(([id, { title }]) => ({ id, title }))
235	  }
236	
237	  async getDocument(id: string): Promise<ReferenceDocument | undefined> {
238	    this.reach()
239	
240	    return this.held.get(id)
241	  }
242	
243	  private reach(): void {
244	    if (!this.reachable) {
245	      throw new Error('The database is unreachable.')
246	    }
247	  }
248	}
